'Warehouses_Tab_Help' => 'আপনার গুদামগুলো (স্টোর/শাখা) পরিচালনা করুন। প্রতিটি গুদামের নিজস্ব স্টক থাকে, এবং প্রতিটি ডকুমেন্ট — বিক্রয়, ক্রয়, স্থানান্তর, সমন্বয় — কোনো একটি গুদামের বিপরীতে রেকর্ড হয়।',
